import numpy as np
import scipy.special._orthogonal as orth

# Test with NaN alpha - should raise ValueError but doesn't
try:
    result_nan = orth.gegenbauer(0, np.nan)
    probe('invalid_alpha_nan_raises', 0.0)  # 0 means no exception raised (bug)
except ValueError:
    probe('invalid_alpha_nan_raises', 1.0)  # 1 means exception raised (correct)

# Test with alpha = -0.5 - should raise ValueError but doesn't
try:
    result_neg_half = orth.gegenbauer(1, -0.5)
    probe('invalid_alpha_neg_half_raises', 0.0)  # 0 means no exception raised (bug)
except ValueError:
    probe('invalid_alpha_neg_half_raises', 1.0)  # 1 means exception raised (correct)

# Test with alpha = -inf - should raise ValueError but doesn't
try:
    result_neginf = orth.gegenbauer(2, -np.inf)
    probe('invalid_alpha_neginf_raises', 0.0)  # 0 means no exception raised (bug)
except ValueError:
    probe('invalid_alpha_neginf_raises', 1.0)  # 1 means exception raised (correct)

